    reachable = {start}
    stack = [start]
    while stack:
        r, c = stack.pop()
        for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 8 and (nr, nc) not in reachable:
                reachable.add((nr, nc))
                stack.append((nr, nc))

    # Keep any connected 1-object that borders this area; clear isolated objects.
    seen = set()
    keep_ones = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            comp = set()
            todo = [(r, c)]
            seen.add((r, c))
            while todo:
                x, y = todo.pop()
                comp.add((x, y))
                for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        todo.append((nx, ny))
            if any(
                0 <= x+dx < h and 0 <= y+dy < w and (x+dx, y+dy) in reachable
                for x, y in comp for dx, dy in ((-1,0),(1,0),(0,-1),(0,1))
            ):
                keep_ones.update(comp)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1 and (r, c) not in keep_ones:
                out[r][c] = 8
            elif grid[r][c] == 8 and (r, c) in reachable:
